package com.c203.limit.domain.inquiry.entity;import java.time.OffsetDateTime;import jakarta.persistence.*;@Entity@Table(name="inquiry_answer")public class InquiryAnswer{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="answer_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="inquiry_id")private Inquiry inquiry;@Column(nullable=false)private int version;@Column(nullable=false,columnDefinition="text")private String content;@Column(name="is_current",nullable=false)private boolean isCurrent;@Column(name="admin_id",nullable=false)private Long adminId;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;protected InquiryAnswer(){}public static InquiryAnswer create(Inquiry q,int version,String content,Long admin){var a=new InquiryAnswer();a.inquiry=q;a.version=version;a.content=content;a.isCurrent=true;a.adminId=admin;a.createdAt=OffsetDateTime.now();return a;}public void supersede(){isCurrent=false;}public Long getId(){return id;}public Inquiry getInquiry(){return inquiry;}public int getVersion(){return version;}public String getContent(){return content;}public boolean isCurrent(){return isCurrent;}public Long getAdminId(){return adminId;}public OffsetDateTime getCreatedAt(){return createdAt;}}
